UPDATE inquiries
SET answer = #{answer}, status = '답변완료', answered_at = NOW()
WHERE inquiry_id = #{inquiryId}

UPDATE inquiries
SET answer = NULL, status = '답변대기', answered_at = NULL
WHERE inquiry_id = #{inquiryId}

UPDATE inquiries
SET title = #{title}, content = #{content}
WHERE inquiry_id = #{inquiryId}
